protected override async Task<AuthenticateResult> HandleAuthenticateAsync()
        {
            var header = Request.Headers.Authorization.ToString();
            if (string.IsNullOrEmpty(header))
            {
                return AuthenticateResult.NoResult();
            }

            // Fail without saying why: a wrong, revoked, expired or malformed token all look the same.
            var presented = header.StartsWith(BearerPrefix, StringComparison.OrdinalIgnoreCase) ? header[BearerPrefix.Length..].Trim() : null;
            var token = await tokens.AuthenticateAsync(presented, Context.RequestAborted);
            if (token is null)
            {
                return AuthenticateResult.Fail("Invalid personal access token.");
            }

            var claims = new List<Claim>
            {
                new(ClaimTypes.NameIdentifier, token.UserId.Value),
                new(ScopeClaim, token.Scope.ToWire()),
                new(PrefixClaim, token.Prefix),
            };
            claims.AddRange(token.Projects is { } limited
                ? limited.Select(p => new Claim(ProjectClaim, p.Value.ToString()))
                : [new Claim(ProjectClaim, AllProjects)]);

            Context.Items[ItemKey] = token;
            var ticket = new AuthenticationTicket(new ClaimsPrincipal(new ClaimsIdentity(claims, PersonalTokenAuthentication.Scheme)), PersonalTokenAuthentication.Scheme);
            return AuthenticateResult.Success(ticket);
        }

protected override Task HandleChallengeAsync(AuthenticationProperties properties)
        {
            Response.Headers.WWWAuthenticate = "Bearer";
            Response.StatusCode = StatusCodes.Status401Unauthorized;
            return Task.CompletedTask;
        }

public static RouteGroupBuilder RequireReporterKey(this RouteGroupBuilder group)
    {
        group.AddEndpointFilter(async (context, next) =>
        {
            var http = context.HttpContext;
            var authenticator = http.RequestServices.GetRequiredService<ApiKeyAuthenticator>();
            var reporter = await authenticator.AuthenticateAsync(http.Request.Headers[Header].ToString(), http.RequestAborted);
            if (reporter is null)
            {
                return Results.Problem(statusCode: StatusCodes.Status401Unauthorized, title: "A valid project API key is required.");
            }

            http.Items[ItemKey] = reporter;
            return await next(context);
        });
        return group;
    }

public async Task SendAsync(IReadOnlyList<AgentTrace> batch, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(batch);
        await using var scope = scopes.CreateAsyncScope();
        var reporter = await scope.ServiceProvider.GetRequiredService<ApiKeyAuthenticator>().AuthenticateAsync(options.Value.ApiKey, ct)
            ?? throw new HttpRequestException("Monday's own API key is not valid.");
        var uploads = batch.Select(t => new TrafficUpload(t.TraceId, t.At, t.Method, t.Route, t.Status, t.DurationMs, t.Guards, t.UserHash, t.ErrorType)).ToList();
        await scope.ServiceProvider.GetRequiredService<TrafficService>().IngestAsync(reporter, uploads, ct);
    }

