        return project;
    }

private async Task SaveAsync(Project project, CancellationToken ct)
    {
        await projects.SaveAsync(project, ct).ConfigureAwait(false);
        foreach (var domainEvent in project.DomainEvents.Where(AuditEntry.IsAudited))
        {
