internal JsonObject BuildBody(ModelRequest request)
    {
        var body = new JsonObject { ["contents"] = BuildContents(request.Messages, NeedsSignatures(settings.Model)) };
        if (!string.IsNullOrEmpty(request.Instructions))
        {
            body["systemInstruction"] = new JsonObject { ["parts"] = new JsonArray { new JsonObject { ["text"] = request.Instructions } } };
        }

        if (request.Tools.Count > 0)
        {
            var declarations = new JsonArray();
            foreach (var tool in request.Tools)
            {
                var declaration = new JsonObject { ["name"] = tool.Name, ["description"] = tool.Description };
                if (Parameters(tool.InputSchema) is { } parameters)
                {
                    declaration["parameters"] = parameters;
                }

                declarations.Add(declaration);
            }

            body["tools"] = new JsonArray { new JsonObject { ["functionDeclarations"] = declarations } };
        }

        return body;
    }

private static JsonArray BuildContents(IReadOnlyList<ChatMessage> history, bool signCalls)
    {
        var contents = new JsonArray();
        var names = new Dictionary<string, string>(StringComparer.Ordinal);
        JsonArray? pendingResults = null;
        foreach (var message in history)
        {
            if (message.Role == ChatRole.Tool && message.ToolResult is { } result)
            {
                // All results for one model turn travel together in a single user turn, tied to their calls by name.
                if (pendingResults is null)
                {
                    pendingResults = [];
                    contents.Add(new JsonObject { ["role"] = "user", ["parts"] = pendingResults });
                }

                pendingResults.Add(new JsonObject
                {
                    ["functionResponse"] = new JsonObject { ["name"] = NameOf(result.CallId, names), ["response"] = ResponseOf(result) },
                });
                continue;
            }

            pendingResults = null;
            if (message.Role == ChatRole.Assistant)
            {
                var parts = new JsonArray();
                if (!string.IsNullOrEmpty(message.Text))
                {
                    parts.Add(new JsonObject { ["text"] = message.Text });
                }

                var first = true;
                foreach (var call in message.ToolCalls ?? [])
                {
                    names[call.Id] = call.Name;
                    var part = new JsonObject { ["functionCall"] = new JsonObject { ["name"] = call.Name, ["args"] = ModelHttp.ArgsNode(call.Args) } };
                    if (signCalls && first)
                    {
                        part["thoughtSignature"] = PlaceholderSignature; // Gemini signs only the first call of a step
                    }

                    first = false;
                    parts.Add(part);
                }

                if (parts.Count == 0)
                {
                    continue; // Gemini rejects a turn with no parts
                }

                contents.Add(new JsonObject { ["role"] = "model", ["parts"] = parts });
            }
            else
            {
                contents.Add(new JsonObject { ["role"] = "user", ["parts"] = new JsonArray { new JsonObject { ["text"] = message.Text ?? string.Empty } } });
            }
        }

        return contents;
    }

private static StopReason MapReason(string reason, bool calledTools) => reason switch
    {
        "STOP" => calledTools ? StopReason.ToolUse : StopReason.EndTurn,
        "MAX_TOKENS" => StopReason.MaxTokens,
        _ => StopReason.Error,
    };

internal static string ModelSegment(string model)
    {
        var name = model.StartsWith("models/", StringComparison.Ordinal) ? model["models/".Length..] : model;
        var valid = name.Length > 0 && char.IsAsciiLetterOrDigit(name[0])
            && name.All(c => char.IsAsciiLetterOrDigit(c) || c is '.' or '-' or '_');
        return valid
            ? Uri.EscapeDataString(name)
            : throw new ModelException("model.rejected", "A Gemini model name can only hold letters, digits, '.', '-' and '_'.");
    }

private static string NameOf(string callId, Dictionary<string, string> names)
    {
        if (names.TryGetValue(callId, out var name))
        {
            return name;
        }

        var dash = callId.LastIndexOf('-');
        var numbered = dash > 0 && dash < callId.Length - 1 && callId.AsSpan(dash + 1).IndexOfAnyExceptInRange('0', '9') < 0;
        return numbered ? callId[..dash] : callId;
    }

private static bool NeedsSignatures(string model)
    {
        var name = model.StartsWith("models/", StringComparison.Ordinal) ? model["models/".Length..] : model;
        return !(name.StartsWith("gemini-1.", StringComparison.Ordinal) || name.StartsWith("gemini-2.", StringComparison.Ordinal));
    }

internal static JsonObject? Parameters(JsonElement schema)
    {
        if (schema.ValueKind != JsonValueKind.Object)
        {
            return null;
        }

        var clean = Sanitize(schema);
        return clean.ContainsKey("properties") || (clean["type"]?.GetValue<string>() is { } type && type != "object") ? clean : null;
    }

private async IAsyncEnumerable<ModelEvent> RunAsync(ModelRequest request, [EnumeratorCancellation] CancellationToken callerCt)
    {
        var endpoint = new Uri(ModelsBase + ModelSegment(settings.Model) + ":streamGenerateContent?alt=sse");

        // Gives up when nothing arrives for IdleTimeout; every line read resets it. GuardAsync turns that into model.unavailable.
        using var idle = CancellationTokenSource.CreateLinkedTokenSource(callerCt);
        idle.CancelAfter(IdleTimeout);
        var ct = idle.Token;
        using var message = new HttpRequestMessage(HttpMethod.Post, endpoint) { Content = ModelHttp.Json(BuildBody(request)) };
        message.Headers.Add("x-goog-api-key", apiKey); // the key goes in a header, never the URL
        using var response = await ModelHttp.SendAsync(http, message, ct).ConfigureAwait(false);
        var stream = await response.Content.ReadAsStreamAsync(ct).ConfigureAwait(false);

        var calls = 0;
        string? finishReason = null;
        var usage = new Usage(0, 0);

        await foreach (var (_, data) in SseReader.ReadAsync(stream, ct, () => idle.CancelAfter(IdleTimeout)).ConfigureAwait(false))
        {
            using var doc = JsonDocument.Parse(data);
            var root = doc.RootElement;
            if (root.TryGetProperty("error", out _))
            {
                throw new ModelException("model.unavailable", "The model provider reported an error mid-stream.");
            }

            if (root.TryGetProperty("usageMetadata", out var u) && u.ValueKind == JsonValueKind.Object)
            {
                // Each chunk carries the running totals. Thinking tokens are billed as output.
                usage = new Usage(Int(u, "promptTokenCount"), Int(u, "candidatesTokenCount") + Int(u, "thoughtsTokenCount"));
            }

            if (root.TryGetProperty("promptFeedback", out var feedback) && feedback.ValueKind == JsonValueKind.Object
                && feedback.TryGetProperty("blockReason", out var block) && block.ValueKind == JsonValueKind.String)
            {
                throw new ModelException("model.rejected", "The model provider blocked this request for safety or policy reasons.");
            }

            if (!root.TryGetProperty("candidates", out var candidates) || candidates.ValueKind != JsonValueKind.Array || candidates.GetArrayLength() == 0)
            {
                continue;
            }

            var candidate = candidates[0];
            if (candidate.TryGetProperty("content", out var content) && content.ValueKind == JsonValueKind.Object
                && content.TryGetProperty("parts", out var parts) && parts.ValueKind == JsonValueKind.Array)
            {
                foreach (var part in parts.EnumerateArray())
                {
                    if (part.TryGetProperty("thought", out var thought) && thought.ValueKind == JsonValueKind.True)
                    {
                        continue; // a thought summary, not answer text
                    }

                    if (part.TryGetProperty("functionCall", out var call) && call.ValueKind == JsonValueKind.Object)
                    {
                        var name = call.TryGetProperty("name", out var n) && n.ValueKind == JsonValueKind.String ? n.GetString() ?? string.Empty : string.Empty;
                        var args = !call.TryGetProperty("args", out var a) ? ModelHttp.ParseArgs("{}")
                            : a.ValueKind == JsonValueKind.Object ? a.Clone() : ModelHttp.ParseArgs(a.GetRawText());
                        yield return new ToolCall($"{name}-{calls++}", name, args); // Gemini has no call id
                    }
                    else if (part.TryGetProperty("text", out var text) && text.ValueKind == JsonValueKind.String && text.GetString() is { Length: > 0 } t)
                    {
                        yield return new TextDelta(t);
                    }
                }
            }

            if (candidate.TryGetProperty("finishReason", out var finish) && finish.ValueKind == JsonValueKind.String)
            {
                finishReason = finish.GetString();
                if (finishReason is not null && BlockedReasons.Contains(finishReason))
                {
                    throw new ModelException("model.rejected", "The model provider blocked this answer for safety or policy reasons.");
                }
            }
        }

        if (finishReason is null)
        {
            throw new ModelException("model.unavailable", "The model provider's stream ended early.");
        }

        yield return new Finished(MapReason(finishReason, calls > 0), usage);
    }

private static JsonObject Sanitize(JsonElement schema)
    {
        var clean = new JsonObject();
        if (schema.ValueKind != JsonValueKind.Object)
        {
            return clean;
        }

        foreach (var property in schema.EnumerateObject())
        {
            var value = property.Value;
            switch (property.Name)
            {
                case "type" when value.ValueKind == JsonValueKind.Array:
                    var types = value.EnumerateArray().Where(t => t.ValueKind == JsonValueKind.String).Select(t => t.GetString()!).ToList();
                    if (types.FirstOrDefault(t => t != "null") is { } single)
                    {
                        clean["type"] = single;
                    }

                    if (types.Contains("null"))
                    {
                        clean["nullable"] = true;
                    }

                    break;
                case "properties" when value.ValueKind == JsonValueKind.Object:
                    var properties = new JsonObject();
                    foreach (var p in value.EnumerateObject())
                    {
                        properties[p.Name] = Sanitize(p.Value);
                    }

                    if (properties.Count > 0)
                    {
                        clean["properties"] = properties;
                    }

                    break;
                case "items":
                    clean["items"] = Sanitize(value);
                    break;
                case "anyOf" when value.ValueKind == JsonValueKind.Array:
                    clean["anyOf"] = new JsonArray([.. value.EnumerateArray().Select(JsonNode (v) => Sanitize(v))]);
                    break;
                case "const" when value.ValueKind == JsonValueKind.String && !schema.TryGetProperty("enum", out _):
                    clean["enum"] = new JsonArray { value.GetString() };
                    break;
                case var name when SchemaKeywords.Contains(name) && name is not ("properties" or "anyOf"):
                    clean[name] = JsonNode.Parse(value.GetRawText());
                    break;
                default:
                    break; // not in Gemini's subset: dropped
            }
        }

        return clean;
    }

public IAsyncEnumerable<ModelEvent> StreamAsync(ModelRequest request, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(request);
        return ModelHttp.GuardAsync(RunAsync(request, ct), ct);
    }

public static async IAsyncEnumerable<T> GuardAsync<T>(IAsyncEnumerable<T> inner, [EnumeratorCancellation] CancellationToken ct)
    {
        await using var enumerator = inner.GetAsyncEnumerator(ct);
        while (true)
        {
            bool more;
            try
            {
                more = await enumerator.MoveNextAsync().ConfigureAwait(false);
            }
            catch (Exception ex) when (ex is HttpRequestException or IOException)
            {
                throw Translate(ex);
            }
            catch (OperationCanceledException) when (!ct.IsCancellationRequested)
            {
                throw new ModelException("model.unavailable", "The model provider stopped sending.");
            }
            catch (Exception ex) when (ex is JsonException or KeyNotFoundException or InvalidOperationException or FormatException)
            {
                throw new ModelException("model.unavailable", "The model provider sent a response Monday could not read.");
            }

            if (!more)
            {
                yield break;
            }

            yield return enumerator.Current;
        }
    }

public static JsonElement ParseArgs(string raw)
    {
        var text = string.IsNullOrWhiteSpace(raw) ? "{}" : raw;
        try
        {
            using var doc = JsonDocument.Parse(text);
            if (doc.RootElement.ValueKind == JsonValueKind.Object)
            {
                return doc.RootElement.Clone();
            }
        }
        catch (JsonException)
        {
            // fall through to the marker
        }

        return JsonSerializer.SerializeToElement(new Dictionary<string, string> { ["_invalid"] = raw });
    }

public static async Task<HttpResponseMessage> SendAsync(HttpClient client, HttpRequestMessage request, CancellationToken ct)
    {
        HttpResponseMessage response;
        try
        {
            response = await client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, ct).ConfigureAwait(false);
        }
        catch (HttpRequestException ex)
        {
            throw Translate(ex);
        }
        catch (TaskCanceledException) when (!ct.IsCancellationRequested)
        {
            throw new ModelException("model.unavailable", "The model provider timed out.");
        }

        if (response.IsSuccessStatusCode)
        {
            return response;
        }

        var status = response.StatusCode;
        response.Dispose();
        throw status switch
        {
            HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden => new ModelException("model.auth", "The model provider refused the key."),
            HttpStatusCode.TooManyRequests => new ModelException("model.rate_limited", "The model provider is rate limiting this key."),
            >= HttpStatusCode.InternalServerError => new ModelException("model.unavailable", "The model provider is unavailable."),
            _ => new ModelException("model.rejected", "The model provider rejected the request."),
        };
    }

private static Exception Translate(Exception ex)
    {
        for (Exception? inner = ex; inner is not null; inner = inner.InnerException)
        {
            if (inner is UnsafeEndpointException)
            {
                return inner;
            }
        }

        return new ModelException("model.unavailable", "The model provider could not be reached.");
    }

private static void Accumulate(SortedDictionary<int, (string Id, string Name, StringBuilder Args)> calls, JsonElement fragment)
    {
        var index = fragment.TryGetProperty("index", out var i) && i.ValueKind == JsonValueKind.Number ? i.GetInt32() : 0;
        if (!calls.TryGetValue(index, out var call))
        {
            call = (string.Empty, string.Empty, new StringBuilder());
        }

        var id = call.Id;
        var name = call.Name;
        if (fragment.TryGetProperty("id", out var idElement) && idElement.ValueKind == JsonValueKind.String)
        {
            id = idElement.GetString() ?? id;
        }

        if (fragment.TryGetProperty("function", out var function) && function.ValueKind == JsonValueKind.Object)
        {
            if (function.TryGetProperty("name", out var n) && n.ValueKind == JsonValueKind.String)
            {
                name = n.GetString() ?? name;
            }

            if (function.TryGetProperty("arguments", out var a) && a.ValueKind == JsonValueKind.String)
            {
                call.Args.Append(a.GetString());
            }
        }

        calls[index] = (id, name, call.Args);
    }

internal JsonObject BuildBody(ModelRequest request)
    {
        var messages = new JsonArray { new JsonObject { ["role"] = "system", ["content"] = request.Instructions } };
        foreach (var message in request.Messages)
        {
            if (message.Role == ChatRole.Tool && message.ToolResult is { } result)
            {
                messages.Add(new JsonObject
                {
                    ["role"] = "tool",
                    ["tool_call_id"] = result.CallId,
                    ["content"] = ModelHttp.RawText(result.Content),
                });
            }
            else if (message.Role == ChatRole.Assistant)
            {
                var node = new JsonObject { ["role"] = "assistant", ["content"] = string.IsNullOrEmpty(message.Text) ? null : message.Text };
                if (message.ToolCalls is { Count: > 0 } calls)
                {
                    var array = new JsonArray();
                    foreach (var call in calls)
                    {
                        array.Add(new JsonObject
                        {
                            ["id"] = call.Id,
                            ["type"] = "function",
                            ["function"] = new JsonObject { ["name"] = call.Name, ["arguments"] = ModelHttp.RawText(call.Args) },
                        });
                    }

                    node["tool_calls"] = array;
                }

                messages.Add(node);
            }
            else
            {
                messages.Add(new JsonObject { ["role"] = "user", ["content"] = message.Text ?? string.Empty });
            }
        }

        var body = new JsonObject
        {
            ["model"] = settings.Model,
            ["messages"] = messages,
            ["stream"] = true,
            ["stream_options"] = new JsonObject { ["include_usage"] = true },
        };
        if (request.Tools.Count > 0)
        {
            var tools = new JsonArray();
            foreach (var tool in request.Tools)
            {
                tools.Add(new JsonObject
                {
                    ["type"] = "function",
                    ["function"] = new JsonObject
                    {
                        ["name"] = tool.Name,
                        ["description"] = tool.Description,
                        ["parameters"] = JsonSerializer.SerializeToNode(tool.InputSchema),
                    },
                });
            }

            body["tools"] = tools;
        }

        return body;
    }

private static StopReason MapReason(string? reason) => reason switch
    {
        "tool_calls" or "function_call" => StopReason.ToolUse,
        "length" => StopReason.MaxTokens,
        "stop" or null => StopReason.EndTurn,
        _ => StopReason.Error,
    };

private async IAsyncEnumerable<ModelEvent> RunAsync(ModelRequest request, [EnumeratorCancellation] CancellationToken callerCt)
    {
        // Gives up when nothing arrives for IdleTimeout; every line read resets it. GuardAsync turns that into model.unavailable.
        using var idle = CancellationTokenSource.CreateLinkedTokenSource(callerCt);
        idle.CancelAfter(IdleTimeout);
        var ct = idle.Token;
        using var message = new HttpRequestMessage(HttpMethod.Post, EndpointUri()) { Content = ModelHttp.Json(BuildBody(request)) };
        message.Headers.TryAddWithoutValidation("Authorization", "Bearer " + apiKey);
        using var response = await ModelHttp.SendAsync(http, message, ct).ConfigureAwait(false);
        var stream = await response.Content.ReadAsStreamAsync(ct).ConfigureAwait(false);

        var calls = new SortedDictionary<int, (string Id, string Name, StringBuilder Args)>();
        string? finishReason = null;
        var usage = new Usage(0, 0);

        await foreach (var (_, data) in SseReader.ReadAsync(stream, ct, () => idle.CancelAfter(IdleTimeout)).ConfigureAwait(false))
        {
            if (data == "[DONE]")
            {
                break;
            }

            using var doc = JsonDocument.Parse(data);
            var root = doc.RootElement;
            if (root.TryGetProperty("error", out _))
            {
                throw new ModelException("model.unavailable", "The model provider reported an error mid-stream.");
            }

            if (root.TryGetProperty("usage", out var u) && u.ValueKind == JsonValueKind.Object)
            {
                usage = new Usage(Int(u, "prompt_tokens"), Int(u, "completion_tokens"));
            }

            if (!root.TryGetProperty("choices", out var choices) || choices.ValueKind != JsonValueKind.Array || choices.GetArrayLength() == 0)
            {
                continue;
            }

            var choice = choices[0];
            if (choice.TryGetProperty("delta", out var delta) && delta.ValueKind == JsonValueKind.Object)
            {
                if (delta.TryGetProperty("content", out var content) && content.ValueKind == JsonValueKind.String && content.GetString() is { Length: > 0 } text)
                {
                    yield return new TextDelta(text);
                }

                if (delta.TryGetProperty("tool_calls", out var fragments) && fragments.ValueKind == JsonValueKind.Array)
                {
                    foreach (var fragment in fragments.EnumerateArray())
                    {
                        Accumulate(calls, fragment);
                    }
                }
            }

            if (choice.TryGetProperty("finish_reason", out var finish) && finish.ValueKind == JsonValueKind.String)
            {
                finishReason = finish.GetString();
                foreach (var (id, name, args) in calls.Values)
                {
                    yield return new ToolCall(string.IsNullOrEmpty(id) ? "call_" + Guid.NewGuid().ToString("N") : id, name, ModelHttp.ParseArgs(args.ToString()));
                }

                var hadCalls = calls.Count > 0;
                calls.Clear();
                if (hadCalls)
                {
                    finishReason = "tool_calls";
                }
            }
        }

        if (finishReason is null)
        {
            throw new ModelException("model.unavailable", "The model provider's stream ended early.");
        }

        yield return new Finished(MapReason(finishReason), usage);
    }

public IAsyncEnumerable<ModelEvent> StreamAsync(ModelRequest request, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(request);
        return ModelHttp.GuardAsync(RunAsync(request, ct), ct);
    }

public static async ValueTask<Stream> ConnectAsync(DnsEndPoint endpoint, Resolver resolve, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(endpoint);
        var addresses = await PublicAddressesAsync(endpoint.Host, resolve, ct).ConfigureAwait(false);
        var socket = new Socket(SocketType.Stream, ProtocolType.Tcp) { NoDelay = true };
        try
        {
            await socket.ConnectAsync(addresses, endpoint.Port, ct).ConfigureAwait(false);
            return new NetworkStream(socket, ownsSocket: true);
        }
        catch
        {
            socket.Dispose();
            throw;
        }
    }

public static SocketsHttpHandler CreateHandler(Resolver? resolve = null)
    {
        var resolver = resolve ?? SystemDns;
        return new SocketsHttpHandler
        {
            UseProxy = false,
            AllowAutoRedirect = false,
            ConnectCallback = (context, ct) => ConnectAsync(context.DnsEndPoint, resolver, ct),
        };
    }

public static async Task EnsurePublicAsync(Uri uri, Resolver resolve, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(uri);
        if (!uri.IsAbsoluteUri || uri.Scheme != Uri.UriSchemeHttps)
        {
            throw new UnsafeEndpointException("model.base_url_https", "The model URL must use HTTPS.");
        }

        _ = await PublicAddressesAsync(uri.IdnHost, resolve, ct).ConfigureAwait(false);
    }

public static bool IsPublic(IPAddress address)
    {
        ArgumentNullException.ThrowIfNull(address);
        if (address.IsIPv4MappedToIPv6)
        {
            address = address.MapToIPv4();
        }

        return address.AddressFamily switch
        {
            AddressFamily.InterNetwork => IsPublicV4(address.GetAddressBytes()),
            AddressFamily.InterNetworkV6 => IsPublicV6(address.GetAddressBytes()),
            _ => false,
        };
    }

private static bool IsPublicV6(byte[] b)
    {
        // 64:ff9b::/96 NAT64 and 2002::/16 6to4 carry an IPv4 address: judge that one.
        if (b[0] == 0x00 && b[1] == 0x64 && b[2] == 0xff && b[3] == 0x9b && b.AsSpan(4, 8).IndexOfAnyExcept((byte)0) < 0)
        {
            return IsPublicV4(b[12..16]);
        }

        if (b[0] == 0x20 && b[1] == 0x02)
        {
            return IsPublicV4(b[2..6]);
        }

        return !(
            b[0] == 0x00                                  // ::/8 unspecified, loopback, IPv4-compatible
            || (b[0] == 0x01 && b[1] == 0x00)             // 100::/64 discard (kept wide: 100::/16)
            || (b[0] == 0x20 && b[1] == 0x01 && b[2] == 0x00 && b[3] == 0x00) // 2001::/32 Teredo
            || (b[0] == 0x20 && b[1] == 0x01 && b[2] == 0x0d && b[3] == 0xb8) // 2001:db8::/32 documentation
            || (b[0] & 0xFE) == 0xFC                      // fc00::/7 unique local, incl. fd00:ec2::254 metadata
            || (b[0] == 0xFE && (b[1] & 0xC0) == 0x80)    // fe80::/10 link-local
            || (b[0] == 0xFE && (b[1] & 0xC0) == 0xC0)    // fec0::/10 site-local (deprecated)
            || b[0] == 0xFF);                             // ff00::/8 multicast
    }

private static async Task<IPAddress[]> PublicAddressesAsync(string host, Resolver resolve, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(resolve);
        var trimmed = host.Trim('[', ']');
        IPAddress[] addresses;
        if (IPAddress.TryParse(trimmed, out var literal))
        {
            addresses = [literal];
        }
        else
        {
            try
            {
                addresses = await resolve(trimmed, ct).ConfigureAwait(false);
            }
            catch (SocketException)
            {
                addresses = [];
            }
        }

        // Every address must be public: a name with one public and one inside answer is refused, since the
        // connection could land on either. The message never names the addresses.
        if (addresses.Length == 0 || !Array.TrueForAll(addresses, IsPublic))
        {
            throw new UnsafeEndpointException("model.base_url_private",
                "The model URL must resolve to a public address, not loopback, private, link-local or metadata.");
        }

        return addresses;
    }

public static async IAsyncEnumerable<(string Event, string Data)> ReadAsync(Stream stream, [EnumeratorCancellation] CancellationToken ct, Action? onActivity = null)
    {
        ArgumentNullException.ThrowIfNull(stream);
        using var reader = new StreamReader(stream, Encoding.UTF8);
        var eventName = string.Empty;
        var data = new StringBuilder();
        var hasData = false;

        while (await reader.ReadLineAsync(ct).ConfigureAwait(false) is { } line)
        {
            onActivity?.Invoke(); // any line, even a keep-alive comment, shows the stream is alive
            if (line.Length == 0)
            {
                if (hasData)
                {
                    yield return (eventName, data.ToString());
                }

                eventName = string.Empty;
                data.Clear();
                hasData = false;
                continue;
            }

            if (line[0] == ':')
            {
                continue; // comment / keep-alive
            }

            var colon = line.IndexOf(':', StringComparison.Ordinal);
            var field = colon < 0 ? line : line[..colon];
            var value = colon < 0 ? string.Empty : line[(colon + 1)..];
            if (value.StartsWith(' '))
            {
                value = value[1..]; // the spec strips exactly one space
            }

            if (field == "event")
            {
                eventName = value;
            }
            else if (field == "data")
            {
                if (hasData)
                {
                    data.Append('\n');
                }

                data.Append(value);
                hasData = true;
            }
        }

        if (hasData)
        {
            yield return (eventName, data.ToString());
        }
    }

public async Task AppendAsync(IReadOnlyList<ActivityEvent> events, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(events);
        await using var batch = db.CreateBatch();
        foreach (var e in events)
        {
            var cmd = new NpgsqlBatchCommand("INSERT INTO activity (project_id, session_id, at, kind, summary, node_ids) VALUES (@p, @s, @at, @k, @sum, @n::jsonb)");
            cmd.Parameters.AddWithValue("p", e.ProjectId.Value);
            cmd.Parameters.AddWithValue("s", e.SessionId);
            cmd.Parameters.AddWithValue("at", e.At);
            cmd.Parameters.AddWithValue("k", e.Kind.ToString());
